import React, { useEffect, useState } from 'react';
import '../App.css';
import './DynamicTable.css';
import { formatRupee } from '../utils/dataUtils';

// Utility function to filter payments due in the current month.
//
// A payment's `date` is treated as its start date, not a one-off due date:
//   - Monthly EMIs (paymentType === 'm') are due EVERY month once they have
//     started, so they should appear in the current month as long as their
//     start date is on/before the end of the current month.
//   - Yearly EMIs (paymentType === 'y') are due once a year, so they only
//     appear when the current month matches their start month (and they have
//     started).
//   - Anything without a recurring paymentType falls back to the original
//     "same calendar month" behaviour.
const getCurrentMonthPayments = (payments) => {
  const now = new Date();
  const currentMonth = now.getMonth();
  const currentYear = now.getFullYear();

  return (payments || []).filter(({ date, paymentType }) => {
    if (!date) return false;
    const start = new Date(date);
    if (isNaN(start.getTime())) return false;

    // Has this payment started yet? (ignore EMIs that begin in a future month)
    const startedByThisMonth =
      start.getFullYear() < currentYear ||
      (start.getFullYear() === currentYear && start.getMonth() <= currentMonth);

    if (paymentType === 'm') {
      // Monthly → due every month once started
      return startedByThisMonth;
    }

    if (paymentType === 'y') {
      // Yearly → due only in its anniversary month, once started
      return startedByThisMonth && start.getMonth() === currentMonth;
    }

    // Fallback: original same-month behaviour
    return start.getMonth() === currentMonth;
  });
};

const STORAGE_KEY = 'paymentDoneChecklist';

const PaymentSummaryTable = ({ payments }) => {
  const currentMonthPayments = getCurrentMonthPayments(payments);
  const currentMonthName = new Date().toLocaleString('default', { month: 'long' });

  const [doneMap, setDoneMap] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
    } catch {
      return {};
    }
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(doneMap));
  }, [doneMap]);

  const toggleDone = (key) => {
    setDoneMap((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="table-container">
      <h3>Payments for {currentMonthName}</h3>
      <table className="responsive-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Payment Type</th>
            <th>Amount</th>
            <th>papers</th>
            <th>Date</th>
            <th>Done</th>
          </tr>
        </thead>
        <tbody>
          {currentMonthPayments.length > 0 ? (
            currentMonthPayments.map(({ name, paymentType, papers, date, paymentAmount }, index) => {
              const key = `${name}_${date}`;
              const done = !!doneMap[key];
              return (
                <tr key={index} style={{ opacity: done ? 0.5 : 1 }}>
                  <td style={{ textDecoration: done ? 'line-through' : 'none' }}>{name}</td>
                  <td>{paymentType === 'm' ? 'Monthly' : 'Yearly'}</td>
                  <td>{formatRupee(paymentAmount)}</td>
                  <td>{papers}</td>
                  <td>{new Date(date).toLocaleDateString()}</td>
                  <td style={{ textAlign: 'center' }}>
                    <input
                      type="checkbox"
                      checked={done}
                      onChange={() => toggleDone(key)}
                      style={{ width: '18px', height: '18px', cursor: 'pointer' }}
                    />
                  </td>
                </tr>
              );
            })
          ) : (
            <tr>
              <td colSpan="6">No payments for this month</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default PaymentSummaryTable;
