import {
  doc,
  getDoc,
  getFirestore,
  serverTimestamp,
  setDoc,
} from "firebase/firestore";
import app from "../firebase/config";

const db = getFirestore(app);

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Safely parse a JSON string. Returns the parsed value or null on failure.
 */
function tryParseJSON(str) {
  if (str === null || str === undefined) return null;
  try {
    return JSON.parse(str);
  } catch {
    return null;
  }
}

/**
 * Extract a stable unique key from an array-item object.
 * Checks the common id fields used across the app:
 *   - BankComponent        → item.id  (Date.now() numeric)
 *   - TodoComponent rows   → item.id
 *   - DynamicTable rows    → item.name + item.bank  (no numeric id)
 *   - Lending rows         → item.name + item.bank
 */
function getItemId(item) {
  if (item === null || typeof item !== "object") return null;
  if (item.id !== undefined && item.id !== null) return String(item.id);
  if (item._id !== undefined && item._id !== null) return String(item._id);
  if (item.key !== undefined && item.key !== null) return String(item.key);
  // Composite key for rows that lack a numeric id
  if (item.name !== undefined && item.bank !== undefined)
    return `${item.name}__${item.bank}`;
  if (item.name !== undefined) return String(item.name);
  return null;
}

/**
 * Merge two arrays without producing duplicates.
 *
 * Strategy:
 *  - If items have a stable unique key (id, _id, key, name+bank, name)
 *    → deduplicate by that key, keeping the entry with the later `updatedAt`
 *    → for equal / missing timestamps the LOCAL item wins
 *    → history sub-arrays are themselves deduplicated by date+amount
 *  - Primitive arrays → simple Set-based dedup
 *  - Items without any recognisable key → full-stringify fallback (safe)
 *
 * @param {Array} local  - items already on this device (higher trust)
 * @param {Array} remote - items coming from the cloud
 * @returns {Array} merged, deduplicated array
 */
function mergeArrays(local, remote) {
  if (!Array.isArray(local)) local = [];
  if (!Array.isArray(remote)) remote = [];

  // Primitive array — simple dedup, local order first
  const firstItem = [...local, ...remote].find((x) => x !== null && x !== undefined);
  if (!firstItem || typeof firstItem !== "object") {
    return Array.from(new Set([...local, ...remote]));
  }

  // Build an ordered map from local items
  const map = new Map();
  const orderedKeys = [];

  local.forEach((item) => {
    const key = getItemId(item) ?? JSON.stringify(item);
    if (!map.has(key)) {
      map.set(key, item);
      orderedKeys.push(key);
    }
  });

  // Merge remote items into the map
  remote.forEach((item) => {
    const key = getItemId(item) ?? JSON.stringify(item);

    if (map.has(key)) {
      const existing = map.get(key);
      const existingTime = existing.updatedAt
        ? new Date(existing.updatedAt).getTime()
        : 0;
      const incomingTime = item.updatedAt
        ? new Date(item.updatedAt).getTime()
        : 0;

      let winner = existing; // local wins by default (equal / no timestamp)
      if (incomingTime > existingTime) {
        // Remote is newer — start from remote, overlay remaining local fields
        winner = { ...existing, ...item };
      }

      // Always merge history sub-arrays (deduplicate by date+amount)
      if (Array.isArray(existing.history) || Array.isArray(item.history)) {
        const histAll = [
          ...(existing.history || []),
          ...(item.history || []),
        ];
        const histMap = new Map();
        histAll.forEach((h) => {
          const hKey = `${h.date}__${h.amount}`;
          if (!histMap.has(hKey)) histMap.set(hKey, h);
        });
        winner = { ...winner, history: Array.from(histMap.values()) };
      }

      map.set(key, winner);
    } else {
      // Brand-new item from remote
      map.set(key, item);
      orderedKeys.push(key);
    }
  });

  // Reconstruct in insertion order (local-first, new remote items at end)
  const seen = new Set();
  const result = [];
  orderedKeys.forEach((k) => {
    if (!seen.has(k) && map.has(k)) {
      result.push(map.get(k));
      seen.add(k);
    }
  });
  map.forEach((val, k) => {
    if (!seen.has(k)) {
      result.push(val);
      seen.add(k);
    }
  });

  return result;
}

/**
 * Merge two plain objects (non-array).
 * Local keys take precedence; remote fills in missing keys.
 */
function mergeObjects(local, remote) {
  return { ...remote, ...local };
}

/**
 * Merge a plain { key: value } object (e.g. parsed from an exported JSON
 * backup file) into localStorage WITHOUT destroying existing data.
 *
 * This is the single shared merge routine used by every file-based / device
 * import path so behaviour is identical no matter which device performs the
 * import:
 *   - `darkMode` is always preserved (never overwritten by an import).
 *   - Key missing locally           → set as-is (brand-new data from cloud/file).
 *   - Both sides are arrays          → mergeArrays() (dedup by stable id,
 *                                      keeps the newer updatedAt, merges history).
 *   - Both sides are plain objects   → mergeObjects() (local wins on conflict).
 *   - Scalar / string values         → local wins (no overwrite) unless the
 *                                      local value is empty.
 *   - Keys that exist only locally   → never touched / never deleted.
 *
 * All values are stored as strings, matching how the rest of the app persists
 * to localStorage.
 *
 * @param {Object} importedData - map of localStorage key → stringified value
 * @returns {{ importedCount: number, newCount: number, updatedCount: number }}
 */
export function mergeImportedDataIntoLocalStorage(importedData) {
  let importedCount = 0;
  let newCount = 0;
  let updatedCount = 0;

  if (!importedData || typeof importedData !== "object") {
    return { importedCount, newCount, updatedCount };
  }

  Object.keys(importedData).forEach((key) => {
    if (key === "darkMode") return; // preserve current theme on every device
    if (key === "lastUpdated" || key === "lastExportedBy") return; // metadata

    const incomingRaw = importedData[key];
    const incomingValue =
      incomingRaw === null || incomingRaw === undefined
        ? ""
        : typeof incomingRaw === "string"
          ? incomingRaw
          : String(incomingRaw);

    const localRaw = localStorage.getItem(key);

    if (localRaw === null) {
      // Brand-new key — safe to set directly
      localStorage.setItem(key, incomingValue);
      newCount++;
      importedCount++;
      return;
    }

    const localParsed = tryParseJSON(localRaw);
    const incomingParsed = tryParseJSON(incomingValue);

    if (Array.isArray(localParsed) && Array.isArray(incomingParsed)) {
      const mergedStr = JSON.stringify(mergeArrays(localParsed, incomingParsed));
      if (mergedStr !== localRaw) {
        localStorage.setItem(key, mergedStr);
        updatedCount++;
      }
    } else if (
      localParsed &&
      incomingParsed &&
      typeof localParsed === "object" &&
      typeof incomingParsed === "object"
    ) {
      const mergedStr = JSON.stringify(mergeObjects(localParsed, incomingParsed));
      if (mergedStr !== localRaw) {
        localStorage.setItem(key, mergedStr);
        updatedCount++;
      }
    } else {
      // Scalar / plain string — local wins, only fill if local is empty
      if (!localRaw && incomingValue) {
        localStorage.setItem(key, incomingValue);
        updatedCount++;
      }
    }

    importedCount++;
  });

  return { importedCount, newCount, updatedCount };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Export all localStorage data to Firestore.
 *
 * Design:
 *   LOCAL data is the source of truth.
 *   Remote-only keys (present in Firestore but deleted locally) are NOT
 *   re-imported during export — export is a one-way push with a safety net
 *   for keys that only exist remotely (they are preserved in Firestore via
 *   { merge: true } so they won't be wiped from the document).
 *
 *   Array fields are merged with the robust mergeArrays() so a repeated
 *   export never duplicates rows.
 */
export const exportDataToFirestore = async (userId) => {
  try {
    console.log("Starting export for user:", userId);

    if (!userId) throw new Error("User ID is required for export");

    // 1. Collect local data
    const localData = {};
    let recordCount = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key === "darkMode") continue;
      localData[key] = localStorage.getItem(key);
      recordCount++;
    }

    console.log(`Collected ${recordCount} records from localStorage`);

    // 2. Fetch existing Firestore document
    const userDocRef = doc(db, "users", userId);
    const existingDoc = await getDoc(userDocRef);

    // 3. Build the payload — start with local data as the base
    const payload = { ...localData };

    if (existingDoc.exists()) {
      const remoteData = existingDoc.data();

      Object.keys(remoteData).forEach((key) => {
        if (key === "lastUpdated" || key === "lastExportedBy") return;

        if (!(key in localData)) {
          // Key only in Firestore — preserve it (don't lose remote-only data)
          payload[key] = remoteData[key];
        } else {
          // Key in both — merge arrays; for other types local wins
          const localParsed = tryParseJSON(localData[key]);
          const remoteParsed = tryParseJSON(remoteData[key]);

          if (Array.isArray(localParsed) && Array.isArray(remoteParsed)) {
            payload[key] = JSON.stringify(mergeArrays(localParsed, remoteParsed));
          } else if (
            localParsed &&
            remoteParsed &&
            typeof localParsed === "object" &&
            typeof remoteParsed === "object"
          ) {
            payload[key] = JSON.stringify(mergeObjects(localParsed, remoteParsed));
          }
          // else local string/number already in payload — keep it
        }
      });
    }

    // 4. Stamp metadata and save
    payload.lastUpdated = serverTimestamp();
    payload.lastExportedBy = userId;

    await setDoc(userDocRef, payload, { merge: true });

    const exportedKeys = Object.keys(payload).filter(
      (k) => k !== "lastUpdated" && k !== "lastExportedBy"
    );
    console.log("Export completed successfully");
    return {
      success: true,
      recordCount: exportedKeys.length,
      message: `Successfully exported ${recordCount} records to cloud`,
    };
  } catch (error) {
    console.error("Export error:", error);
    return {
      success: false,
      error: error.message,
      message: `Failed to export: ${error.message}`,
    };
  }
};

/**
 * Import data from Firestore into localStorage.
 *
 * Design:
 *   - Arrays are merged using the robust mergeArrays() (dedup by unique key).
 *   - Plain objects are merged (remote fills missing keys, local wins conflicts).
 *   - Scalar strings: local wins unless remote is strictly newer
 *     (checked via lastUpdated timestamp stored in metadata — not per key).
 *   - Keys that only exist locally are never deleted.
 *   - Metadata keys (lastUpdated, lastExportedBy) are never written to localStorage.
 */
export const importDataFromFirestore = async (userId) => {
  try {
    console.log("Starting import for user:", userId);

    if (!userId) throw new Error("User ID is required for import");

    const userDocRef = doc(db, "users", userId);
    const docSnap = await getDoc(userDocRef);

    if (!docSnap.exists()) {
      return {
        success: false,
        recordCount: 0,
        message: "No data found in cloud. Export data first.",
      };
    }

    const remoteData = docSnap.data();
    console.log("Firestore data found, merging with local data...");

    // Snapshot current local state
    const localSnapshot = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key !== "darkMode") localSnapshot[key] = localStorage.getItem(key);
    }

    let recordCount = 0;
    let newCount = 0;
    let updatedCount = 0;

    Object.keys(remoteData).forEach((key) => {
      if (key === "lastUpdated" || key === "lastExportedBy") return;

      const remoteRaw = remoteData[key];
      // Firestore can store Timestamps — convert to string if needed
      const remoteValue =
        remoteRaw && typeof remoteRaw === "object" && remoteRaw.toDate
          ? remoteRaw.toDate().toISOString()
          : String(remoteRaw ?? "");

      const localValue = localSnapshot[key] ?? null;

      if (localValue === null) {
        // Brand-new key from cloud
        localStorage.setItem(key, remoteValue);
        newCount++;
        recordCount++;
        return;
      }

      // Both sides have data — merge
      const localParsed = tryParseJSON(localValue);
      const remoteParsed = tryParseJSON(remoteValue);

      if (Array.isArray(localParsed) && Array.isArray(remoteParsed)) {
        const merged = mergeArrays(localParsed, remoteParsed);
        const mergedStr = JSON.stringify(merged);
        if (mergedStr !== localValue) {
          localStorage.setItem(key, mergedStr);
          updatedCount++;
        }
        recordCount++;
      } else if (
        localParsed &&
        remoteParsed &&
        typeof localParsed === "object" &&
        typeof remoteParsed === "object"
      ) {
        const merged = mergeObjects(localParsed, remoteParsed);
        const mergedStr = JSON.stringify(merged);
        if (mergedStr !== localValue) {
          localStorage.setItem(key, mergedStr);
          updatedCount++;
        }
        recordCount++;
      } else {
        // Scalar / plain string — local wins (no overwrite)
        // Only update if local is completely empty
        if (!localValue && remoteValue) {
          localStorage.setItem(key, remoteValue);
          updatedCount++;
        }
        recordCount++;
      }
    });

    const message = [
      `Successfully imported ${recordCount} records from cloud`,
      newCount > 0 ? `${newCount} new` : null,
      updatedCount > 0 ? `${updatedCount} merged` : null,
    ]
      .filter(Boolean)
      .join(" | ");

    console.log("Import completed:", message);
    return { success: true, recordCount, newCount, updatedCount, message };
  } catch (error) {
    console.error("Import error:", error);
    return {
      success: false,
      error: error.message,
      message: `Failed to import: ${error.message}`,
    };
  }
};
