
import React, { useState } from 'react';
import '../App.css';
import './DynamicTable.css'
import { formatRupee } from '../utils/dataUtils';

// Utility function to calculate monthly payment totals for a specific calendar
// year.
//
// The stored `date` is treated as the EMI's start date, so an EMI only
// contributes to a month if it had already started by that month/year:
//   - Monthly ('m'): counts in every month of `targetYear` that is on or after
//     the start month/year. (e.g. an EMI starting Aug 2026 counts Aug-Dec 2026,
//     and Jan-Dec 2027, Jan-Dec 2028, ...).
//   - Yearly ('y'): counts once, in its anniversary month, for every year on or
//     after the start year.
const calculateMonthlyTotals = (payments, targetYear) => {
  let monthlyTotals = Array(12).fill(0); // Jan - Dec

  (payments || []).forEach(({ paymentType, paymentAmount, date }) => {
    if (!paymentType || !paymentAmount || !date) return; // Skip invalid data

    const amount = Number(paymentAmount) || 0;
    const startDate = new Date(date);
    if (isNaN(startDate.getTime())) return;

    const startMonth = startDate.getMonth();
    const startYear = startDate.getFullYear();

    if (paymentType === 'm') {
      for (let i = 0; i < 12; i++) {
        const startedByThisMonth =
          targetYear > startYear ||
          (targetYear === startYear && i >= startMonth);
        if (startedByThisMonth) monthlyTotals[i] += amount;
      }
    } else if (paymentType === 'y') {
      // Due only in its anniversary month, for years on/after the start year
      if (targetYear >= startYear) {
        monthlyTotals[startMonth] += amount;
      }
    }
  });

  return monthlyTotals;
};

const PaymentSummaryTable = ({ payments }) => {
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  const monthlyTotals = calculateMonthlyTotals(payments, selectedYear);
  const yearTotal = monthlyTotals.reduce((sum, amount) => sum + amount, 0);

  return (
    <div className="table-container">
      <h3>Total Payment Summary</h3>
      <table className="responsive-table">
        <thead>
          <tr>
            <th>Month</th>
            <th>Total Amount</th>
          </tr>
        </thead>
        <tbody>
          {monthlyTotals.map((amount, index) => (
            <tr key={index}>
              <td>{new Date(selectedYear, index, 1).toLocaleString('default', { month: 'long' })} {selectedYear}</td>
              <td>{formatRupee(amount)}</td>
            </tr>
          ))}
          <tr>
            <td><strong>Total ({selectedYear})</strong></td>
            <td><strong>{formatRupee(yearTotal)}</strong></td>
          </tr>
        </tbody>
      </table>


      <div style={{ marginBottom: '10px' }}>
        <button
          onClick={() => setSelectedYear((y) => y - 1)}
          aria-label="Previous year"
        >
          &lt;
        </button>
        <span style={{ margin: '0 8px', fontWeight: 'bold' }}>{selectedYear}</span>
        <button
          onClick={() => setSelectedYear((y) => y + 1)}
          aria-label="Next year"
        >
          &gt;
        </button>
      </div>

    </div>
  );
};

export default PaymentSummaryTable;