import { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import "../App.css";

const ASSET_SOURCES = [
  { key: "balance_tracker_bank",          label: "Bank",          color: "#376c58", icon: "🏦", route: "/bank" },
  { key: "balance_tracker_mutual_fund",   label: "Mutual Fund",   color: "#1a6fb5", icon: "📈", route: "/mutual-fund" },
  { key: "balance_tracker_us_mutual_fund",label: "US Mutual Fund",color: "#0d47a1", icon: "🇺🇸", route: "/us-mf" },
  { key: "balance_tracker_btc",           label: "BTC",           color: "#f57c00", icon: "₿",  route: "/btc" },
  { key: "balance_tracker_gold",          label: "Gold",          color: "#c8a000", icon: "🪙", route: "/gold-assets" },
  { key: "balance_tracker_real_estate",   label: "Real Estate",   color: "#795548", icon: "🏠", route: "/real-estate" },
];

const AssetsReportComponent = () => {
  const navigate = useNavigate();
  const formatCurrency = (val) =>
    val.toLocaleString("en-IN", { maximumFractionDigits: 2 });

  const assets = useMemo(() => {
    return ASSET_SOURCES.map((src) => {
      try {
        const raw = localStorage.getItem(src.key);
        const entries = raw ? JSON.parse(raw) : [];
        const total = entries.reduce((sum, e) => sum + (e.balance || 0), 0);
        return { ...src, entries, total };
      } catch {
        return { ...src, entries: [], total: 0 };
      }
    });
  }, []);

  const grandTotal = assets.reduce((sum, a) => sum + a.total, 0);

  return (
    <div className="counter-app">
      <div className="todo-container">
        <h1>Report</h1>

        {/* Grand Total Card */}
        <div
          style={{
            backgroundColor: "#376c58",
            borderRadius: "12px",
            padding: "16px 20px",
            marginBottom: "20px",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            color: "#fff",
          }}
        >
          <span style={{ fontSize: "15px", fontWeight: "600" }}> Net Worth</span>
          <span style={{ fontSize: "20px", fontWeight: "700" }}>
            ₹{formatCurrency(grandTotal)}
          </span>
        </div>

        {/* Asset Summary Cards */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))",
            gap: "10px",
            marginBottom: "24px",
          }}
        >
          {assets.map((asset) => (
            <div
              key={asset.key}
              onClick={() => navigate(asset.route)}
              style={{
                backgroundColor: "#f9f9f9",
                border: `2px solid ${asset.color}22`,
                borderRadius: "10px",
                padding: "12px",
                textAlign: "center",
                cursor: "pointer",
                transition: "transform 0.15s, box-shadow 0.15s",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = "translateY(-2px)";
                e.currentTarget.style.boxShadow = `0 4px 12px ${asset.color}33`;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = "translateY(0)";
                e.currentTarget.style.boxShadow = "none";
              }}
            >
              <div style={{ fontSize: "22px", marginBottom: "4px" }}>{asset.icon}</div>
              <div style={{ fontSize: "12px", color: "#666", marginBottom: "4px" }}>{asset.label}</div>
              <div style={{ fontSize: "14px", fontWeight: "700", color: asset.color }}>
                ₹{formatCurrency(asset.total)}
              </div>
              <div style={{ fontSize: "11px", color: "#999", marginTop: "2px" }}>
                {asset.entries.length} {asset.entries.length === 1 ? "entry" : "entries"}
              </div>
            </div>
          ))}
        </div>

        {/* Portfolio % Bar */}
        {grandTotal > 0 && (
          <div style={{ marginBottom: "24px" }}>
            <div style={{ fontSize: "13px", fontWeight: "600", color: "#444", marginBottom: "8px" }}>
              Portfolio Breakdown
            </div>
            <div style={{ display: "flex", borderRadius: "8px", overflow: "hidden", height: "20px" }}>
              {assets.filter(a => a.total > 0).map((asset) => (
                <div
                  key={asset.key}
                  title={`${asset.label}: ${((asset.total / grandTotal) * 100).toFixed(1)}%`}
                  style={{
                    width: `${(asset.total / grandTotal) * 100}%`,
                    backgroundColor: asset.color,
                    transition: "width 0.3s",
                  }}
                />
              ))}
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "8px", marginTop: "8px" }}>
              {assets.filter(a => a.total > 0).map((asset) => (
                <div key={asset.key} style={{ display: "flex", alignItems: "center", gap: "4px", fontSize: "11px", color: "#555" }}>
                  <span style={{ width: "10px", height: "10px", borderRadius: "50%", backgroundColor: asset.color, display: "inline-block" }} />
                  {asset.label} ({((asset.total / grandTotal) * 100).toFixed(1)}%)
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Detailed Entries per Asset */}
        {assets.map((asset) => (
          asset.entries.length > 0 && (
            <div key={asset.key} style={{ marginBottom: "20px" }}>
              {/* Section Header */}
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "8px 12px",
                  backgroundColor: `${asset.color}15`,
                  borderLeft: `4px solid ${asset.color}`,
                  borderRadius: "6px",
                  marginBottom: "8px",
                }}
              >
                <span style={{ fontWeight: "600", fontSize: "13px", color: asset.color }}>
                  {asset.icon} {asset.label}
                </span>
                <span style={{ fontWeight: "700", fontSize: "13px", color: asset.color }}>
                  ₹{formatCurrency(asset.total)}
                </span>
              </div>

              {/* Entries */}
              {asset.entries.map((entry, idx) => (
                <div
                  key={entry.id || idx}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    padding: "8px 12px",
                    backgroundColor: idx % 2 === 0 ? "#fafafa" : "#fff",
                    borderRadius: "6px",
                    marginBottom: "4px",
                    border: "1px solid #f0f0f0",
                  }}
                >
                  <div>
                    <div style={{ fontSize: "13px", fontWeight: "600", color: "#333" }}>
                      {entry.name}
                    </div>
                    <div style={{ fontSize: "11px", color: "#999" }}>
                      {entry.ownerName} · Updated: {new Date(entry.updatedAt).toLocaleDateString("en-IN", {
                        day: "2-digit", month: "short", year: "numeric",
                      })}
                    </div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: "14px", fontWeight: "700", color: asset.color }}>
                      ₹{formatCurrency(entry.balance)}
                    </div>
                    {grandTotal > 0 && (
                      <div style={{ fontSize: "10px", color: "#aaa" }}>
                        {((entry.balance / grandTotal) * 100).toFixed(1)}% of total
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )
        ))}

        {grandTotal === 0 && (
          <p style={{ textAlign: "center", color: "#999", marginTop: "40px" }}>
            No asset data found. Add entries in Bank, MF, US MF, BTC or Gold.
          </p>
        )}
      </div>
    </div>
  );
};

export default AssetsReportComponent;
