import { useState, useEffect } from "react";
import "../App.css";


const BankComponent = ({ headLine }) => {
  const [banks, setBanks] = useState([]);
  const [bankName, setBankName] = useState("");
  const [ownerName, setOwnerName] = useState("");
  const [balance, setBalance] = useState("");
  const [expandedId, setExpandedId] = useState(null);
  const [editId, setEditId] = useState(null);
  const [editBalance, setEditBalance] = useState("");
  const [showHistoryId, setShowHistoryId] = useState(null);

  const storageKey = `balance_tracker_${headLine?.toLowerCase().replace(/\s+/g, "_")}`;

  useEffect(() => {
    const saved = localStorage.getItem(storageKey);
    if (saved) {
      try {
        setBanks(JSON.parse(saved));
      } catch (e) {
        console.error("Error loading bank data:", e);
      }
    }
  }, [storageKey]);

  const saveBanks = (updated) => {
    localStorage.setItem(storageKey, JSON.stringify(updated));
    setBanks(updated);
  };

  const handleAdd = () => {
    if (!bankName.trim() || balance === "") return;
    const parsed = parseFloat(balance);
    if (isNaN(parsed)) return;

    const newBank = {
      id: Date.now(),
      name: bankName.trim(),
      balance: parsed,
      ownerName: ownerName.trim() || "Unknown",
      updatedAt: new Date().toISOString(),
    };
    saveBanks([...banks, newBank]);
    setBankName("");
    setBalance("");
    setOwnerName("");
  };

  const handleDelete = (id) => {
    if (window.confirm("Delete this bank entry?")) {
      saveBanks(banks.filter((b) => b.id !== id));
      if (expandedId === id) setExpandedId(null);
    }
  };

  const handleEditSave = (id) => {
    const parsed = parseFloat(editBalance);
    if (isNaN(parsed)) return;
    saveBanks(
      banks.map((b) => {
        if (b.id !== id) return b;
        const historyEntry = {
          amount: b.balance,
          date: new Date().toISOString(),
        };
        const prevHistory = b.history || [];
        return {
          ...b,
          balance: parsed,
          updatedAt: new Date().toISOString(),
          history: [historyEntry, ...prevHistory],
        };
      })
    );
    setEditId(null);
    setEditBalance("");
  };

  const totalBalance = banks.reduce((sum, b) => sum + b.balance, 0);

  const formatCurrency = (val) =>
    val.toLocaleString("en-IN", { maximumFractionDigits: 2 });

  return (
    <div className="counter-app">
      <div className="todo-container">
        <h1>{headLine}</h1>

        {/* Add Bank Form */}
        <div className="pm-form">
          
          <input
            type="text"
            className="pm-input"
            placeholder="Office"
            value={bankName}
            onChange={(e) => setBankName(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") handleAdd(); }}
          />
          <input
            type="number"
            className="pm-input"
            placeholder="Amount (₹)"
            value={balance}
            onChange={(e) => setBalance(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") handleAdd(); }}
          />

          <input
            type="text"
            className="pm-input"
            placeholder="Owner Name"
            value={ownerName}
            onChange={(e) => setOwnerName(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") handleAdd(); }}
          />
          <div className="pm-actions">
            <button className="add-button pm-btn" onClick={handleAdd}>
              Add
            </button>
          </div>
        </div>

        {/* Bank List */}
        <div className="todo-list">
          {banks.length === 0 ? (
            <p style={{ textAlign: "center", color: "#999" }}>
              No {headLine} added.
            </p>
          ) : (
            banks.map((bank) => (
              <div key={bank.id} className="todo-item pm-item">
                {/* Collapsed View */}
                <div
                  onClick={() =>
                    setExpandedId(expandedId === bank.id ? null : bank.id)
                  }
                  style={{
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    gap: "10px",
                    fontWeight: "500",
                  }}
                >
                  <span style={{ fontSize: "14px" }}>
                    {expandedId === bank.id ? "▼" : "▶"}
                  </span>
                  <span style={{ flex: 1, textAlign: "left" }}>{bank.name}</span>
                  <span style={{ color: "#376c58", fontWeight: "600" }}>
                    ₹{formatCurrency(bank.balance)}
                  </span>
                </div>

                {/* Expanded View */}
                {expandedId === bank.id && (
                  <div className="pm-detail">
                    <div className="pm-detail-row">
                      <span className="pm-detail-label">Bank</span>
                      <span className="pm-detail-value">{bank.name}</span>
                    </div>

                    <div className="pm-detail-row">
                      <span className="pm-detail-label">Name</span>
                      <span className="pm-detail-value">{bank.ownerName}</span>
                    </div>

                    <div className="pm-detail-row">
                      <span className="pm-detail-label">Balance</span>
                      {editId === bank.id ? (
                        <input
                          type="number"
                          className="pm-input"
                          style={{ flex: 1, padding: "4px 8px", fontSize: "14px" }}
                          value={editBalance}
                          onChange={(e) => setEditBalance(e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === "Enter") handleEditSave(bank.id);
                          }}
                          autoFocus
                        />
                      ) : (
                        <span className="pm-detail-value">
                          ₹{formatCurrency(bank.balance)}
                        </span>
                      )}
                    </div>

                    <div className="pm-detail-actions">
                      {editId === bank.id ? (
                        <>
                          <button
                            className="pm-detail-btn"
                            style={{ backgroundColor: "#28a745" }}
                            onClick={() => handleEditSave(bank.id)}
                          >
                            ✓ Save
                          </button>
                          <button
                            className="pm-detail-btn"
                            style={{ backgroundColor: "#6c757d" }}
                            onClick={() => { setEditId(null); setEditBalance(""); }}
                          >
                            ✕ Cancel
                          </button>
                        </>
                      ) : (
                        <>
                          <button
                            className="pm-detail-btn pm-detail-btn--copy"
                            onClick={(e) => {
                              e.stopPropagation();
                              setEditId(bank.id);
                              setEditBalance(bank.balance.toString());
                            }}
                          >
                            ✏ Edit
                          </button>
                          <button
                            className="pm-detail-btn pm-detail-btn--delete"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDelete(bank.id);
                            }}
                          >
                            🗑 Delete
                          </button>
                        </>
                      )}
                    </div>

                    <div className="pm-detail-date">
                      Updated: {new Date(bank.updatedAt).toLocaleDateString()}
                    </div>

                    {/* Inline Balance History */}
                    {bank.history && bank.history.length > 0 && (
                      <div style={{ marginTop: "10px", borderTop: "1px dashed #ddd", paddingTop: "10px" }}>
                        {/* Toggle Header */}
                        <div
                          onClick={(e) => {
                            e.stopPropagation();
                            setShowHistoryId(showHistoryId === bank.id ? null : bank.id);
                          }}
                          style={{
                            display: "flex",
                            justifyContent: "space-between",
                            alignItems: "center",
                            cursor: "pointer",
                            userSelect: "none",
                          }}
                        >
                          <span style={{ fontSize: "12px", color: "#6f42c1", fontWeight: "600" }}>
                            📋 Balance History ({bank.history.length})
                          </span>
                          <span style={{ fontSize: "11px", color: "#6f42c1" }}>
                            {showHistoryId === bank.id ? "▲ Hide" : "▼ Show"}
                          </span>
                        </div>

                        {/* History Entries */}
                        {showHistoryId === bank.id && (
                          <div style={{ marginTop: "8px" }}>
                            {bank.history.map((entry, idx) => (
                              <div
                                key={idx}
                                style={{
                                  display: "flex",
                                  justifyContent: "space-between",
                                  alignItems: "center",
                                  padding: "6px 8px",
                                  backgroundColor: idx % 2 === 0 ? "#f9f5ff" : "#fff",
                                  borderRadius: "6px",
                                  marginBottom: "4px",
                                }}
                              >
                                <div>
                                  <span style={{ fontSize: "13px", fontWeight: "600", color: "#333" }}>
                                    ₹{formatCurrency(entry.amount)}
                                  </span>
                                  <span style={{ fontSize: "11px", color: "#999", marginLeft: "8px" }}>
                                    {new Date(entry.date).toLocaleString("en-IN", {
                                      day: "2-digit", month: "short", year: "numeric",
                                      hour: "2-digit", minute: "2-digit",
                                    })}
                                  </span>
                                </div>
                                <span style={{
                                  fontSize: "10px",
                                  backgroundColor: "#ede9ff",
                                  color: "#6f42c1",
                                  padding: "2px 6px",
                                  borderRadius: "10px",
                                }}>
                                  #{bank.history.length - idx}
                                </span>
                              </div>
                            ))}

                            {/* Clear History */}
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                if (window.confirm("Clear all history for this bank?")) {
                                  saveBanks(banks.map((b) =>
                                    b.id === bank.id ? { ...b, history: [] } : b
                                  ));
                                  setShowHistoryId(null);
                                }
                              }}
                              style={{
                                marginTop: "8px",
                                width: "100%",
                                padding: "6px",
                                backgroundColor: "#fff0f0",
                                color: "#dc3545",
                                border: "1px solid #f5c6cb",
                                borderRadius: "6px",
                                cursor: "pointer",
                                fontSize: "12px",
                                fontWeight: "600",
                              }}
                            >
                              🗑 Clear History
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
            ))
          )}
        </div>

        {/* Total Balance */}
        {banks.length > 0 && (
          <div
            style={{
              marginTop: "12px",
              padding: "10px",
              borderTop: "1px solid #ccc",
              display: "flex",
              justifyContent: "space-between",
              fontWeight: "600",
              fontSize: "15px",
            }}
          >
            <span>Total</span>
            <span style={{ color: "#376c58" }}>₹{formatCurrency(totalBalance)}</span>
          </div>
        )}
      </div>

    </div>
  );
};

export default BankComponent;
