import React, { useState, useEffect } from 'react';
import './DynamicTable.css';
import TodoComponent from '../components/TodoComponent';
import PaymentSummaryTable from '../components/PaymentSummaryTable';
import CurrentMonthPendingPayment from '../components/CurrentMonthPendingPayment';
import { data, useNavigate } from 'react-router-dom';
import { formatRupee } from '../utils/dataUtils';

const DynamicTable = ({ filter, name }) => {
  const navigate = useNavigate();

  const loadRowsFromLocalStorage = () => {
    const savedRows = localStorage.getItem(filter);
    return savedRows ? JSON.parse(savedRows) : [];
  };

  const initialLastUpdated = localStorage.getItem(`${filter +'lastUpdated'}`) ? new Date(localStorage.getItem(`${filter +'lastUpdated'}`)) : new Date();
  const [lastUpdated, setLastUpdated] = useState(initialLastUpdated);

  const [total, setTotal] = useState(0);
  const [inHand, setInHand] = useState(0);
  const [inHandAsset, setInHandAsset] = useState(0);
  const [yearlyPayable, setYearlyPayable] = useState(0);
  const [selectedLendingRow, setSelectedLendingRow] = useState(null);
  const [rows, setRows] = useState(loadRowsFromLocalStorage);

  // Total amount payable across a full year for all lending entries.
  // Monthly payments (paymentType === 'm') recur 12 times a year; yearly
  // payments (paymentType === 'y') are counted once.
  const calculateYearlyPayable = (lendingRows) =>
    lendingRows.reduce((sum, { paymentType, paymentAmount }) => {
      const amount = parseFloat(paymentAmount) || 0;
      if (paymentType === 'm') return sum + amount * 12;
      if (paymentType === 'y') return sum + amount;
      return sum;
    }, 0);

  useEffect(() => {
    calculateTotal();
  }, [rows]);

  const calculateTotal = () => {
    if (filter === 'bank' || filter === 'mf') {
      setTotal(
        rows
          .filter((account) => account.type === 'mf')
          .map((account) => parseFloat(account.balance))
          .reduce((total, balance) => total + balance, 0)
      );

      setInHand(
        rows
          .filter((account) => account.type === 'bank')
          .map((account) => parseFloat(account.balance))
          .reduce((total, balance) => total + balance, 0)
      );
    }

    if (filter === 'lending') {
      setTotal(
        rows.map((account) => parseFloat(account.balance)).reduce((total, balance) => total + balance, 0)
      );

      setInHandAsset(
        rows
          .filter((account) => account.isAsset === 'y')
          .map((account) => parseFloat(account.quantity))
          .reduce((total, balance) => total + balance, 0)
      );

      setYearlyPayable(calculateYearlyPayable(rows));
    }
  };

  useEffect(() => {
    localStorage.setItem(filter, JSON.stringify(rows));
  }, [rows]);

  return (
    <div className="table-container">
      <h2>{name}</h2>
      <div className="form">
        <button onClick={() => navigate('/add-row', { state: { filter } })}>Add New</button>
      </div>
      <table className="responsive-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Vendor</th>
            <th>Amount</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => (
            <tr key={index}>
              <td>{row.name}</td>
              <td>{row.bank}</td>
              <td>{formatRupee(row.balance)}</td>
              <td>
                <button onClick={() => navigate('/edit-row', { state: { filter, rowData: row, index } })}>Edit</button>
                {filter === 'lending' && (
                  <button onClick={() => setSelectedLendingRow(row)}>Detail</button>
                )}
              </td>
            </tr>
          ))}

          {/* Total and In-Hand only shown in main table for bank/mf */}
          {(filter === 'bank' || filter === 'mf') && (
            <>
              <tr>
                <td>Total :</td>
                <td></td>
                <td>{formatRupee(total)}</td>
                <td></td>
              </tr>
              <tr>
                <td>In-Hand :</td>
                <td></td>
                <td>{formatRupee(inHand)}</td>
                <td></td>
              </tr>
            </>
          )}

        </tbody>
      </table>

      {filter === 'lending' && selectedLendingRow && (
        <div className="table-container">
          <h3>Lending Details</h3>
          <table className="responsive-table">
            <tbody>
              <tr>
                <th>Name</th>
                <td>{selectedLendingRow.name || '-'}</td>
              </tr>
              <tr>
                <th>Vendor</th>
                <td>{selectedLendingRow.bank || '-'}</td>
              </tr>
              <tr>
                <th>Lend Amount</th>
                <td>{formatRupee(selectedLendingRow.balance)}</td>
              </tr>
              <tr>
                <th>Payment Type</th>
                <td>
                  {selectedLendingRow.paymentType === 'm'
                    ? 'Monthly'
                    : selectedLendingRow.paymentType === 'y'
                      ? 'Yearly'
                      : '-'}
                </td>
              </tr>
              <tr>
                <th>Payment Amount</th>
                <td>{formatRupee(selectedLendingRow.paymentAmount)}</td>
              </tr>
              <tr>
                <th>Start Date</th>
                <td>
                  {selectedLendingRow.date
                    ? new Date(selectedLendingRow.date).toLocaleDateString('en-IN')
                    : '-'}
                </td>
              </tr>
              <tr>
                <th>Asset</th>
                <td>{selectedLendingRow.isAsset === 'y' ? 'Yes' : 'No'}</td>
              </tr>
              <tr>
                <th>Asset Quantity</th>
                <td>
                  {selectedLendingRow.isAsset === 'y' && selectedLendingRow.quantity
                    ? `${selectedLendingRow.quantity} g`
                    : '-'}
                </td>
              </tr>
              <tr>
                <th>Papers</th>
                <td>{selectedLendingRow.papers || '-'}</td>
              </tr>
            </tbody>
          </table>
          <button onClick={() => setSelectedLendingRow(null)}>Close</button>
        </div>
      )}

      Last Updated : {lastUpdated.toLocaleString()}

   

      {filter === 'lending' && <CurrentMonthPendingPayment payments={rows} />}


      {filter === 'lending' && <PaymentSummaryTable payments={rows} />}

         {filter === 'lending' && (
        <div className="table-container">
          <h3>L Details</h3>
          <table className="responsive-table">
            <thead>
              <tr>
                <th>Metric</th>
                <th>Amount</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Total Lend Amount</td>
                <td>{formatRupee(total)}</td>
              </tr>
              <tr>
                <td>Asset Quantity</td>
                <td>{inHandAsset + ' g'}</td>
              </tr>
              <tr>
                <td>Total Yearly Payable</td>
                <td>{formatRupee(yearlyPayable)}</td>
              </tr>
              <tr>
                <td>Yearly Avg / Month</td>
                <td>{formatRupee(yearlyPayable / 12)}</td>
              </tr>
            </tbody>
          </table>
        </div>
      )}

      <div style={{ paddingTop: '50px' }}>
        <TodoComponent filter={`${filter + '-key'}`} name="notes" />
      </div>
    </div>
  );
};

export default DynamicTable;