import { useState } from "react";
import "../App.css";
import "./DynamicTable.css";
import { formatRupee } from "../utils/dataUtils";

const STORAGE_KEY = "balance_tracker_gold";

const createGoldItem = () => ({ name: "", quantity: "" });

const emptyForm = {
  items: [createGoldItem()],
  vendor: "",
  balance: "",
  purchaseDate: "",
  papers: "",
};

const loadGoldPurchases = () => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : [];
  } catch (error) {
    console.error("Error loading gold purchases:", error);
    return [];
  }
};

const formatDate = (date) => {
  if (!date) return "-";
  const [year, month, day] = date.split("-");
  return year && month && day ? `${day}/${month}/${year}` : date;
};

// Existing Gold entries used one set of name/quantity/quality fields. Treat
// them as a one-item purchase so old saved data stays visible and editable.
const getPurchaseItems = (purchase) =>
  Array.isArray(purchase.items) && purchase.items.length > 0
    ? purchase.items
    : [{
        name: purchase.name || "",
        quantity: purchase.quantity ?? "",
      }];

const getTotalQuantity = (items) =>
  items.reduce((sum, item) => sum + (parseFloat(item.quantity) || 0), 0);

const GoldAssetsComponent = () => {
  const [purchases, setPurchases] = useState(loadGoldPurchases);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [selectedPurchase, setSelectedPurchase] = useState(null);

  const savePurchases = (updatedPurchases) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedPurchases));
    setPurchases(updatedPurchases);
  };

  const handleChange = ({ target: { name, value } }) => {
    setForm((current) => ({ ...current, [name]: value }));
  };

  const handleItemChange = (index, field, value) => {
    setForm((current) => ({
      ...current,
      items: current.items.map((item, itemIndex) =>
        itemIndex === index ? { ...item, [field]: value } : item
      ),
    }));
  };

  const addItem = () => {
    setForm((current) => ({ ...current, items: [...current.items, createGoldItem()] }));
  };

  const removeItem = (index) => {
    setForm((current) => ({
      ...current,
      items: current.items.filter((_, itemIndex) => itemIndex !== index),
    }));
  };

  const resetForm = () => {
    setForm(emptyForm);
    setEditingId(null);
    setShowForm(false);
  };

  const beginAdd = () => {
    setForm(emptyForm);
    setEditingId(null);
    setSelectedPurchase(null);
    setShowForm(true);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    const amount = parseFloat(form.balance);
    const items = form.items
      .map((item) => ({
        name: item.name.trim(),
        quantity: item.quantity,
      }))
      .filter((item) => item.name);

    if (items.length === 0 || isNaN(amount)) return;

    const primaryItem = items[0];
    const purchaseData = {
      // `items` is the source of truth for a multi-item purchase.
      items,
      // Keep these legacy-compatible fields populated for the existing Assets
      // Report and for any older device that still reads a single item.
      name: primaryItem.name,
      quantity: getTotalQuantity(items),
      bank: form.vendor.trim(),
      vendor: form.vendor.trim(),
      balance: amount,
      purchaseDate: form.purchaseDate,
      papers: form.papers.trim(),
      updatedAt: new Date().toISOString(),
    };

    if (editingId !== null) {
      const updated = purchases.map((purchase, index) =>
        (purchase.id ?? index) === editingId
          ? { ...purchase, ...purchaseData }
          : purchase
      );
      savePurchases(updated);
      setSelectedPurchase((current) =>
        current && (current.id ?? purchases.indexOf(current)) === editingId
          ? { ...current, ...purchaseData }
          : current
      );
    } else {
      savePurchases([{ id: Date.now(), ...purchaseData }, ...purchases]);
    }

    resetForm();
  };

  const beginEdit = (purchase, index) => {
    setEditingId(purchase.id ?? index);
    setForm({
      items: getPurchaseItems(purchase).map((item) => ({
        name: item.name || "",
        quantity: item.quantity ?? "",
      })),
      vendor: purchase.vendor || purchase.bank || "",
      balance: purchase.balance ?? "",
      purchaseDate: purchase.purchaseDate || "",
      papers: purchase.papers || "",
    });
    setSelectedPurchase(null);
    setShowForm(true);
  };

  const deletePurchase = (purchase, index) => {
    if (!window.confirm(`Are you sure you want to delete "${purchase.name}"?`)) return;
    const purchaseId = purchase.id ?? index;
    savePurchases(
      purchases.filter((item, itemIndex) => (item.id ?? itemIndex) !== purchaseId)
    );
    if ((selectedPurchase?.id ?? -1) === purchaseId) setSelectedPurchase(null);
    if (editingId === purchaseId) resetForm();
  };

  const totalPaid = purchases.reduce(
    (sum, purchase) => sum + (parseFloat(purchase.balance) || 0),
    0
  );
  const totalQuantity = purchases.reduce(
    (sum, purchase) => sum + getTotalQuantity(getPurchaseItems(purchase)),
    0
  );

  return (
    <div className="table-container">
      <h2>Assets</h2>

      <div className="form">
        <button onClick={beginAdd}>Add</button>
      </div>

      {showForm && (
        <form className="pm-form" onSubmit={handleSubmit}>
          <input className="pm-input" name="vendor" placeholder="vendor" value={form.vendor} onChange={handleChange} />
          <input className="pm-input" type="number" min="0" step="any" name="balance" placeholder="Purchase amount (₹)" value={form.balance} onChange={handleChange} required />
          {form.balance !== "" && <small className="amount-preview">{formatRupee(form.balance)}</small>}
          <input className="pm-input" type="date" name="purchaseDate" value={form.purchaseDate} onChange={handleChange} />
          <input className="pm-input" name="papers" placeholder="Notes / papers" value={form.papers} onChange={handleChange} />

          <div className="gold-items-group">
            <strong className="gold-items-title">Gold Items</strong>
            {form.items.map((item, index) => (
              <div className="gold-item-row" key={index}>
                <span className="gold-item-index">#{index + 1}</span>
                <input className="pm-input" placeholder="Gold item (e.g. Ring)" value={item.name} onChange={(event) => handleItemChange(index, "name", event.target.value)} required />
                <input className="pm-input" type="number" min="0" step="any" placeholder="Quantity (g)" value={item.quantity} onChange={(event) => handleItemChange(index, "quantity", event.target.value)} />
                {form.items.length > 1 && <button type="button" className="delete-btn" onClick={() => removeItem(index)}>Remove</button>}
              </div>
            ))}
            <button type="button" className="gold-add-item-btn" onClick={addItem}>+ Add Item</button>
          </div>

          <div className="pm-actions">
            <button className="add-button pm-btn" type="submit">{editingId !== null ? "Save" : "Add"}</button>
            {editingId !== null && (
              <button
                className="pm-btn pm-detail-btn--delete"
                type="button"
                onClick={() => {
                  const index = purchases.findIndex(
                    (purchase, purchaseIndex) => (purchase.id ?? purchaseIndex) === editingId
                  );
                  if (index !== -1) deletePurchase(purchases[index], index);
                }}
              >
                Delete
              </button>
            )}
            <button className="pm-btn" type="button" onClick={resetForm}>Cancel</button>
          </div>
        </form>
      )}

      <table className="responsive-table">
        <thead>
          <tr>
            <th>Vendor</th>
            <th>Item</th>
            <th>Quantity</th>
            <th>Date</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {purchases.length === 0 ? (
            <tr><td colSpan="5">No gold purchases added.</td></tr>
          ) : purchases.map((purchase, index) => (
            <tr key={purchase.id ?? index}>
              <td>{purchase.vendor || purchase.bank || "-"}</td>
              <td>{getPurchaseItems(purchase).map((item) => item.name).filter(Boolean).join(", ") || "-"}</td>
              <td>{getTotalQuantity(getPurchaseItems(purchase)) || "-"}{getTotalQuantity(getPurchaseItems(purchase)) ? " g" : ""}</td>
              <td>{formatDate(purchase.purchaseDate)}</td>
              <td className="action-buttons">
                <button onClick={() => setSelectedPurchase(purchase)}>Detail</button>
                <button onClick={() => beginEdit(purchase, index)}>Edit</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {selectedPurchase && (
        <div className="table-container">
          <h3>Details</h3>
          <table className="responsive-table"><tbody>
            <tr><th>Vendor</th><td>{selectedPurchase.vendor || selectedPurchase.bank || "-"}</td></tr>
            <tr><th>Total Quantity</th><td>{getTotalQuantity(getPurchaseItems(selectedPurchase))} g</td></tr>
            <tr><th>Purchase</th><td>{formatRupee(selectedPurchase.balance)}</td></tr>
            <tr><th>Date</th><td>{formatDate(selectedPurchase.purchaseDate)}</td></tr>
            <tr><th>Notes / Papers</th><td>{selectedPurchase.papers || "-"}</td></tr>
          </tbody></table>
          <h4>Items</h4>
          <table className="responsive-table">
            <thead><tr><th>Item</th><th>Quantity</th></tr></thead>
            <tbody>
              {getPurchaseItems(selectedPurchase).map((item, index) => (
                <tr key={index}>
                  <td>{item.name || "-"}</td>
                  <td>{item.quantity ? `${item.quantity} g` : "-"}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <button onClick={() => setSelectedPurchase(null)}>Close</button>
        </div>
      )}

      {purchases.length > 0 && (
        <div className="table-container">
          <h3>Summary</h3>
          <table className="responsive-table"><tbody>
            <tr><th>Count</th><td>{purchases.length}</td></tr>
            <tr><th>Total Quantity</th><td>{totalQuantity} g</td></tr>
            <tr><th>Total Amount</th><td>{formatRupee(totalPaid)}</td></tr>
          </tbody></table>
        </div>
      )}
    </div>
  );
};

export default GoldAssetsComponent;
