
import React from "react";
import { mergeImportedDataIntoLocalStorage } from "../services/firestoreService";

const ImportLocalStorage = () => {
  const handleFileUpload = (event) => {
    const file = event.target.files[0]; // Get the selected file
    const reader = new FileReader();   // Create a FileReader instance

    // When file is read
    reader.onload = (e) => {
      try {
        // Parse the JSON data
        const jsonData = JSON.parse(e.target.result);

        // Merge into localStorage without destroying existing data.
        // Uses the shared merge routine so importing on any device only ADDS
        // new data and reconciles arrays/objects — it never overwrites newer
        // local records or wipes keys that only exist on this device.
        const { importedCount, newCount, updatedCount } =
          mergeImportedDataIntoLocalStorage(jsonData);

        alert(
          `Data merged successfully! ${importedCount} items processed` +
            (newCount ? `, ${newCount} new` : "") +
            (updatedCount ? `, ${updatedCount} merged` : "") +
            "."
        );
      } catch (error) {
        console.error("Error parsing JSON:", error);
        alert("Invalid JSON file. Please check the format.");
      }
    };

    // Handle file read errors
    reader.onerror = () => {
      console.error("File reading error");
      alert("Failed to read the file. Please try again.");
    };

    // Read the file as text
    reader.readAsText(file);
  };

  return (
    <div style={{ padding: "20px", border: "1px solid #ccc", borderRadius: "5px" }}>
      <h2>Import JSON to LocalStorage</h2>
      <input
        type="file"
        accept=".json"
        onChange={handleFileUpload}
        style={{ margin: "10px 0" }}
      />
    </div>
  );
};

export default ImportLocalStorage;
